# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FİZİKSEL (MEKANİK) VE KİMYASAL SİNDİRİM KARŞILAŞTIRMASI</text>\n  <rect x="30" y="50" width="305" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Fiziksel (Mekanik) Sindirim</text>\n  <text x="48" y="102" font-size="11.5" fill="#334155">• Besinlerin çiğneme ve kas hareketleriyle</text>\n  <text x="48" y="120" font-size="11.5" fill="#334155">  küçük parçalara ayrılmasıdır.</text>\n  <text x="48" y="146" font-size="11.5" font-weight="bold" fill="#1e40af">• Enzim KULLANILMAZ, su harcanmaz.</text>\n  <text x="48" y="172" font-size="11.5" fill="#334155">• Temas yüzeyini artırarak kimyasal</text>\n  <text x="48" y="190" font-size="11.5" fill="#334155">  sindirimi kolaylaştırır ve hızlandırır.</text>\n  <text x="48" y="214" font-size="11" font-weight="bold" fill="#1d4ed8">Örnek: Dişlerle çiğneme, mide kasları, safra sıvısı.</text>\n  <rect x="365" y="50" width="305" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Kimyasal Sindirim</text>\n  <text x="383" y="102" font-size="11.5" fill="#334155">• Besinlerin su ve ENZİMLER yardımıyla</text>\n  <text x="383" y="120" font-size="11.5" fill="#334155">  hücre zarından geçecek yapı taşlarına</text>\n  <text x="383" y="138" font-size="11.5" fill="#334155">  kadar parçalanmasıdır.</text>\n  <text x="383" y="164" font-size="11.5" font-weight="bold" fill="#166534">• Enzim ve su KULLANILIR.</text>\n  <text x="383" y="190" font-size="11.5" fill="#334155">• Gerçekleştiği organlar: Ağız, Mide</text>\n  <text x="383" y="208" font-size="11.5" fill="#334155">  ve İnce Bağırsak.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SİNDİRİM KANALI ORGANLARI VE BESİNLERİN YOLCULUĞU</text>\n  <rect x="20" y="45" width="205" height="92" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="122" y="65" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. Ağız</text>\n  <text x="32" y="84" font-size="10.5" fill="#334155">• Diş ve dil: Fiziksel sindirim.</text>\n  <text x="32" y="102" font-size="10.5" fill="#334155">• Tükürük: Karbonhidratların</text>\n  <text x="32" y="118" font-size="10.5" font-weight="bold" fill="#1e40af">  kimyasal sindirimi BAŞLAR.</text>\n  <rect x="247" y="45" width="205" height="92" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="350" y="65" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">2. Yutak ve 3. Yemek Borusu</text>\n  <text x="260" y="84" font-size="10.5" fill="#334155">• Yutak: Besini yemek borusuna</text>\n  <text x="260" y="102" font-size="10.5" fill="#334155">  iletir. Yemek borusu: Kasılıp</text>\n  <text x="260" y="118" font-size="10.5" font-weight="bold" fill="#92400e">  gevşer (SİNDİRİM OLMAZ!).</text>\n  <rect x="475" y="45" width="205" height="92" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="577" y="65" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">4. Mide</text>\n  <text x="488" y="84" font-size="10.5" fill="#334155">• Kaslarla çalkalama: Fiziksel.</text>\n  <text x="488" y="102" font-size="10.5" fill="#334155">• Mide öz suyu (enzim + asit):</text>\n  <text x="488" y="118" font-size="10.5" font-weight="bold" fill="#991b1b">  Proteinlerin kimyasal sindirimi BAŞLAR.</text>\n  <rect x="20" y="150" width="320" height="95" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="180" y="170" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">5. İnce Bağırsak (En Uzun Bölüm)</text>\n  <text x="34" y="190" font-size="10.5" fill="#334155">• Yağların fiziksel (safra) ve kimyasal sindirimi BAŞLAR.</text>\n  <text x="34" y="208" font-size="10.5" font-weight="bold" fill="#166534">• Karbonhidrat, protein ve yağların sindirimi TAMAMLANIR.</text>\n  <text x="34" y="226" font-size="10.5" fill="#334155">• Villuslar (tümürler) ile sindirilmiş besinler kana EMİLİR.</text>\n  <rect x="360" y="150" width="320" height="95" rx="8" fill="#f3e8ff" stroke="#a855f7"/>\n  <text x="520" y="170" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">6. Kalın Bağırsak ve 7. Anüs</text>\n  <text x="374" y="190" font-size="10.5" fill="#334155">• Kalın bağırsakta fiziksel veya kimyasal sindirim OLMAZ.</text>\n  <text x="374" y="208" font-size="10.5" font-weight="bold" fill="#6b21a8">• Su, vitamin ve minerallerin emilimi tamamlanır (villus yok).</text>\n  <text x="374" y="226" font-size="10.5" fill="#334155">• Besin atıkları anüs yoluyla vücuttan dışarı atılır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">YARDIMCI ORGANLAR (KARACİĞER VE PANKREAS) VE BESİN TABLOSU</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Sindirime Yardımcı Organlar</text>\n  <text x="40" y="98" font-size="11.5" font-weight="bold" fill="#92400e">1. Karaciğer → Safra Sıvısı Üretir</text>\n  <text x="40" y="116" font-size="10.5" fill="#334155">• Safra enzim İÇERMEZ; büyük yağ damlalarını küçük</text>\n  <text x="40" y="132" font-size="10.5" fill="#334155">  yağ damlacıklarına ayırır (FİZİKSEL sindirim).</text>\n  <text x="40" y="160" font-size="11.5" font-weight="bold" fill="#92400e">2. Pankreas → Pankreas Öz Suyu Üretir</text>\n  <text x="40" y="178" font-size="10.5" fill="#334155">• İçerdiği enzimlerle ince bağırsakta karbonhidrat,</text>\n  <text x="40" y="194" font-size="10.5" fill="#334155">  protein ve yağların KİMYASAL sindirimini sağlar.</text>\n  <text x="40" y="218" font-size="10.5" font-weight="bold" fill="#b45309">* Her iki salgı da İNCE BAĞIRSAĞA (onikiparmak) dökülür.</text>\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kimyasal Sindirim Başlangıç ve Bitiş Özeti</text>\n  <text x="376" y="102" font-size="11.5" font-weight="bold" fill="#1e40af">• Karbonhidratlar:</text>\n  <text x="386" y="120" font-size="11" fill="#334155">Başlar: Ağız (tükürük) → Biter: İnce bağırsak</text>\n  <text x="376" y="148" font-size="11.5" font-weight="bold" fill="#1e40af">• Proteinler:</text>\n  <text x="386" y="166" font-size="11" fill="#334155">Başlar: Mide (mide öz suyu) → Biter: İnce bağırsak</text>\n  <text x="376" y="194" font-size="11.5" font-weight="bold" fill="#1e40af">• Yağlar:</text>\n  <text x="386" y="212" font-size="11" fill="#334155">Başlar: İnce bağırsak → Biter: İnce bağırsak</text>\n  <text x="376" y="232" font-size="10.5" font-weight="bold" fill="#15803d">* Su, vitamin ve mineraller sindirilmeden emilir!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
